package br.com.loja;import br.com.loja.auth.*;import br.com.loja.product.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.Bean;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;@SpringBootApplication public class StoreApplication{public static void main(String[]a){SpringApplication.run(StoreApplication.class,a);}@Bean CommandLineRunner seed(AppUserRepository users,ProductRepository p,PasswordEncoder enc){return a->{if(users.findByEmail("admin@teste.com").isEmpty())users.save(new AppUser(null,"Administrador da Loja","admin@teste.com",enc.encode("123456"),Role.ADMIN));if(users.findByEmail("usuario@teste.com").isEmpty())users.save(new AppUser(null,"Cliente Demo","usuario@teste.com",enc.encode("123456"),Role.USER));if(p.count()==0){p.save(new Product(null,"L001","Headset Gamer","Headset confortável com microfone.","Periféricos",new BigDecimal("249.90"),12,true));p.save(new Product(null,"L002","Mousepad XL","Mousepad grande para mesa.","Periféricos",new BigDecimal("79.90"),30,true));p.save(new Product(null,"L003","Webcam Full HD","Webcam 1080p para aulas e reuniões.","Vídeo",new BigDecimal("319.90"),5,true));}};}}